WITH enriched AS (SELECT a.id, a.full_name, a.manager_id, a.job_title, a.salary, a.level, p.salary AS employee_salary, p.level AS employee_level FROM employees a LEFT JOIN employees p ON a.manager_id = p.id WHERE p.level = 'L4'), base AS (SELECT id, full_name, manager_id, job_title, level, employee_salary, employee_level, SUBSTRING(job_title, 1, 2) AS job_title_prefix, COALESCE(job_title, 'Unknown') AS job_title_filled FROM enriched WHERE manager_id IS NULL), joined AS (SELECT a.id, a.full_name, a.manager_id, a.job_title, a.job_title_prefix, p.email FROM base a INNER JOIN employees p ON a.manager_id = p.id), enriched_employees AS (SELECT a.id, a.full_name, a.manager_id, a.job_title, a.email, d.email AS employee_email, d.full_name AS employee_full_name, d.salary FROM joined a LEFT JOIN employees d ON a.manager_id <=> d.id), filtered AS (SELECT id, full_name, manager_id, job_title, employee_full_name, salary, UPPER(TRIM(full_name)) AS full_name_normalized FROM enriched_employees WHERE manager_id IS NOT NULL) SELECT CASE WHEN salary >= 139000 THEN 'LARGE' ELSE 'SMALL' END AS salary_tier, job_title, SUM(CASE WHEN job_title = 'Engineer' THEN salary ELSE 0 END) AS engineer_salary, ROUND(SUM(salary) / NULLIF(COUNT(CASE WHEN job_title = 'Intern' THEN 1 END), 0), 2) AS salary_per_intern, GROUPING(CASE WHEN salary >= 139000 THEN 'LARGE' ELSE 'SMALL' END) AS grouping_id FROM filtered GROUP BY GROUPING SETS ((CASE WHEN salary >= 139000 THEN 'LARGE' ELSE 'SMALL' END, job_title), (CASE WHEN salary >= 139000 THEN 'LARGE' ELSE 'SMALL' END), ()) ORDER BY job_title NULLS LAST;
